+        color: var(--color-bg);
+        transform: translateY(-200%);
+      }
+
+      .skip-link:focus {
+        transform: translateY(0);
+        z-index: 10;
+      }
+
+      main {
+        min-height: 100vh;
+        display: grid;
+        place-items: center;
+        padding: 1.5rem;
+      }
+
+      .panel {
+        width: min(100%, 28rem);
+        padding: 1.5rem;
+        border: 1px solid var(--color-border);
+        border-radius: 1.25rem;
+        background: linear-gradient(180deg, var(--color-panel) 0%, var(--color-panel-alt) 100%);
+        box-shadow: 0 24px 60px rgba(0, 0, 0, 0.35);
+      }
+
+      h1 {
+        margin: 0 0 0.75rem;
+        font-size: clamp(1.8rem, 5vw, 2.4rem);
+        line-height: 1.1;
+      }
+
+      .intro {
+        margin: 0 0 1.5rem;
+        color: var(--color-muted-text);
+        line-height: 1.5;
+      }
+
+      form {
+        display: grid;
+        gap: 1rem;
+      }
+
+      .form-field {
+        display: grid;
+        gap: 0.5rem;
+        padding: 1rem;
+        border: 1px solid var(--color-border);
+        border-radius: 1rem;
+        background: #0f1730;
+      }
+
+      .checkbox-row {
+        display: grid;
+        grid-template-columns: auto 1fr;
+        align-items: start;
+        gap: 0.75rem;
+      }
+
+      input[type="checkbox"] {
+        width: 1.2rem;
+        height: 1.2rem;
+        margin: 0.15rem 0 0;
+        accent-color: var(--color-button);
+      }
+
+      label {
+        font-weight: 600;
+        line-height: 1.5;
+      }
+
+      a {
+        color: var(--color-link);
+      }
+
+      .required-marker {
+        color: var(--color-focus);
+      }
+
+      .helper-text,
+      .error-text,
+      .status-text {
+        margin: 0;
+        font-size: 0.95rem;
+        line-height: 1.45;
+      }
+
+      .helper-text {
+        color: var(--color-muted-text);
+      }
+
+      .error-text {
+        color: var(--color-danger);
+      }
+
+      .status-text {
+        min-height: 1.45em;
+        color: var(--color-success);
+      }
+
+      button {
+        border: 0;
+        border-radius: 999px;
+        padding: 0.95rem 1.2rem;
+        font: inherit;
+        font-weight: 700;
+        color: var(--color-button-text);
+        background: linear-gradient(180deg, #a1adff 0%, var(--color-button) 100%);
+        cursor: pointer;
+      }
+
+      button:hover {
+        filter: brightness(1.05);
+      }
+
+      a:focus-visible,
+      button:focus-visible,
+      input[type="checkbox"]:focus-visible {
+        outline: 3px solid var(--color-focus);
+        outline-offset: 3px;
+      }
+
+      @media (max-width: 30rem) {
+        .panel {
+          padding: 1.25rem;
+        }
+      }
+
+      @media (forced-colors: active) {
+        body {
+          background: Canvas;
+          color: CanvasText;
+        }
+
+        .panel,
+        .form-field,
+        button {
+          border: 1px solid ButtonBorder;
+          background: Canvas;
+          color: CanvasText;
+          box-shadow: none;
+        }
+
+        a {
+          color: LinkText;
+        }
+
+        .error-text {
+          color: CanvasText;
+        }
+
+        .status-text {
+          color: CanvasText;
+        }
+      }
+    </style>
+  </head>
+  <body>
+    <a class="skip-link" href="#maincontent">Skip to main content</a>
+
+    <main id="maincontent" tabindex="-1">
+      <section class="panel" aria-labelledby="page-title">
+        <h1 id="page-title">Confirm your consent</h1>
+        <p class="intro">Review the requirement below, then continue when you are ready.</p>
+
+        <form id="consent-form" novalidate>
+          <div class="form-field">
+            <div class="checkbox-row">
+              <input
+                id="consent"
+                name="consent"
+                type="checkbox"
+                required
+                aria-describedby="consent-help"
+              />
+              <label for="consent">
+                I agree to the <a href="#terms">terms of use</a>
+                <span class="required-marker" aria-hidden="true">*</span>
+              </label>
+            </div>
+            <p id="consent-help" class="helper-text">Required before submitting.</p>
+            <p id="consent-error" class="error-text" hidden>
+              Error: You must agree to the terms of use before continuing.
+            </p>
+          </div>
+
+          <button type="submit">Continue</button>
+          <p id="form-status" class="status-text" role="status" aria-live="polite"></p>
+        </form>
+      </section>
+    </main>
+
+    <script>
+      const form = document.getElementById("consent-form");
+      const checkbox = document.getElementById("consent");
+      const error = document.getElementById("consent-error");
+      const status = document.getElementById("form-status");
+
+      function showError() {
+        checkbox.setAttribute("aria-invalid", "true");
+        checkbox.setAttribute("aria-describedby", "consent-help consent-error");
+        error.hidden = false;
+        status.textContent = "";
+      }
+
+      function clearError() {
+        checkbox.removeAttribute("aria-invalid");
+        checkbox.setAttribute("aria-describedby", "consent-help");
+        error.hidden = true;
+      }
+
+      form.addEventListener("submit", function (event) {
+        event.preventDefault();
+
+        if (!checkbox.checked) {
+          showError();
+          checkbox.focus();
+          return;
+        }
+
+        clearError();
+        status.textContent = "Consent recorded. You can proceed.";
+      });
+
+      checkbox.addEventListener("change", function () {
+        if (checkbox.checked) {
+          clearError();
+        }
+      });
+    </script>
+  </body>
+</html>
*** End Patch
