        <form id="consent-form" novalidate>
          <div class="form-field">
            <div class="checkbox-row">
              <input
                id="consent"
                name="consent"
                type="checkbox"
                required
                aria-describedby="consent-help"
              />
              <label for="consent">
                I agree to the <a href="#terms">terms of use</a>
                <span class="required-marker" aria-hidden="true">*</span>
              </label>
            </div>
            <p id="consent-help" class="helper-text">Required before submitting.</p>
            <p id="consent-error" class="error-text" hidden>
              Error: You must agree to the terms of use before continuing.
            </p>
          </div>

          <button type="submit">Continue</button>
          <p id="form-status" class="status-text" role="status" aria-live="polite"></p>
        </form>
      </section>
    </main>

