 <!DOCTYPE html>
 <html lang="en">
   <head>
     <meta charset="UTF-8" />
     <meta name="viewport" content="width=device-width, initial-scale=1.0" />
     <title>Consent form - Terms of use</title>
     <style>
       :root {
         color-scheme: dark;
         --color-bg: #0b1020;
         --color-panel: #131a2e;
         --color-panel-alt: #1b2440;
         --color-text: #f3f7ff;
