         box-shadow: 0 24px 60px rgba(0, 0, 0, 0.35);
       }

       h1 {
         margin: 0 0 0.75rem;
         font-size: clamp(1.8rem, 5vw, 2.4rem);
         line-height: 1.1;
       }

       .intro {
         margin: 0 0 1.5rem;
         color: var(--color-muted-text);
         line-height: 1.5;
       }

       form {
         display: grid;
         gap: 1rem;
       }

       .form-field {
         display: grid;
         gap: 0.5rem;
         padding: 1rem;
         border: 1px solid var(--color-border);
         border-radius: 1rem;
         background: #0f1730;
       }

       .checkbox-row {
         display: grid;
         grid-template-columns: auto 1fr;
         align-items: start;
         gap: 0.75rem;
